const memoryPercent = msg.payload.memory.freeHeapPercent;
const threshold = 20;

if (memoryPercent < threshold) {
    // Check if we've already alerted recently (prevent spam)
    const now = Date.now();
    const lastAlert = context.get('lastAlert') || 0;
    const cooldown = 5 * 60 * 1000; // 5 minutes

    if (now - lastAlert > cooldown) {
        context.set('lastAlert', now);
        msg.payload = {
            alert: true,
            memory: memoryPercent,
            threshold: threshold,
            message: `⚠️ LOW MEMORY ALERT: ${memoryPercent}% free (threshold: ${threshold}%)`
        };
        return msg;
    }
}

// No alert needed
return null;

// This would send to Telegram, Email, SMS, etc.
// For now, just format the message
msg.topic = 'ESP32 MMDVM Alert';
msg.payload = msg.payload.message;
return msg;

// Define your watchlist here
const watchlist = ['PD2EMC', 'N0CALL', 'W1AW'];

const slots = msg.payload.slots;
const alerts = [];

for (const slot of slots) {
    if (slot.active && slot.srcCallsign) {
        if (watchlist.includes(slot.srcCallsign)) {
            // Check if we haven't already notified about this transmission
            const key = `${slot.srcCallsign}_${slot.slotNo}`;
            const alerted = context.get(key) || false;

            if (!alerted) {
                context.set(key, true);
                alerts.push({
                    callsign: slot.srcCallsign,
                    name: slot.srcName,
                    talkgroup: slot.dstId,
                    slot: slot.slotNo,
                    duration: slot.duration
                });

                // Clear the alert flag after 30 seconds
                setTimeout(() => {
                    context.set(key, false);
                }, 30000);
            }
        }
    }
}

if (alerts.length > 0) {
    msg.payload = {
        alerts: alerts,
        message: alerts.map(a => 
            `🎤 ${a.callsign} (${a.name}) on TG${a.talkgroup} Slot ${a.slot}`
        ).join('\n')
    };
    return msg;
}

return null;

const history = msg.payload.history;
const logged = context.get('logged') || new Set();
const newEntries = [];

// Only log entries we haven't seen before
for (const entry of history) {
    const key = `${entry.timestamp}_${entry.srcId}_${entry.dstId}`;
    if (!logged.has(key)) {
        logged.add(key);
        newEntries.push({
            timestamp: entry.timestamp,
            callsign: entry.srcCallsign,
            name: entry.srcName,
            dmr_id: entry.srcId,
            location: entry.srcLocation,
            talkgroup: entry.dstId,
            is_group: entry.isGroup,
            duration: entry.duration,
            ber: entry.ber,
            rssi: entry.rssi,
            slot: entry.slotNo
        });
    }
}

// Keep only last 100 logged entries to prevent memory growth
if (logged.size > 100) {
    const arr = Array.from(logged);
    context.set('logged', new Set(arr.slice(-100)));
} else {
    context.set('logged', logged);
}

if (newEntries.length > 0) {
    msg.payload = newEntries;
    return msg;
}

return null;

const entries = msg.payload;
const csvLines = [];

for (const entry of entries) {
    const line = [
        entry.timestamp,
        entry.callsign,
        entry.name,
        entry.dmr_id,
        entry.talkgroup,
        entry.duration,
        entry.rssi,
        entry.ber,
        entry.slot
    ].join(',');
    csvLines.push(line);
}

msg.payload = csvLines.join('\n');
msg.filename = '/tmp/dmr_log.csv'; // Change to your desired path

return msg;

const entries = msg.payload;
const points = [];

for (const entry of entries) {
    points.push({
        measurement: 'dmr_transmission',
        tags: {
            callsign: entry.callsign,
            talkgroup: entry.talkgroup.toString(),
            slot: entry.slot.toString()
        },
        fields: {
            duration: entry.duration,
            rssi: entry.rssi,
            ber: entry.ber,
            dmr_id: entry.dmr_id,
            name: entry.name,
            location: entry.location
        },
        timestamp: new Date(entry.timestamp)
    });
}

msg.payload = points;
return msg;

